import pytest
import os
import tempfile
from envcfg import load_config, ConfigError


def test_basic_loading():
    defaults = {'a': 1, 'b': 'hello', 'c': True}
    config = load_config(defaults)
    assert config == defaults


def test_toml_loading():
    defaults = {'a': 1, 'b': {'c': 2}}
    with tempfile.NamedTemporaryFile(mode='w', suffix='.toml', delete=False) as f:
        f.write('a = 10\nb = { c = 20 }\nd = "extra"')
        f.flush()

        config = load_config(defaults, f.name)
        assert config == {'a': 10, 'b': {'c': 20}, 'd': 'extra'}

        os.unlink(f.name)


def test_env_loading():
    defaults = {'a': 1, 'b': {'c': 2}}
    env = {'TEST__A': '10', 'TEST__B__C': '20'}
    config = load_config(defaults, env_prefix='TEST', env_dict=env)
    assert config == {'a': 10, 'b': {'c': 20}}


def test_type_coercion():
    defaults = {'a': 1, 'b': 2.5, 'c': True, 'd': 'hello'}
    env = {'TEST__A': '10', 'TEST__B': '20.5', 'TEST__C': 'false', 'TEST__D': 'world'}
    config = load_config(defaults, env_prefix='TEST', env_dict=env)
    assert config == {'a': 10, 'b': 20.5, 'c': False, 'd': 'world'}


def test_unknown_env_var():
    defaults = {'a': 1}
    env = {'TEST__B': '10'}  # B is not in defaults
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='TEST', env_dict=env)
    assert "Unknown configuration key: b" in str(excinfo.value)


def test_invalid_coercion():
    defaults = {'a': 1}
    env = {'TEST__A': 'not_a_number'}
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='TEST', env_dict=env)
    assert "Error in TEST__A: invalid literal for int()" in str(excinfo.value)


def test_missing_toml():
    defaults = {'a': 1}
    config = load_config(defaults, 'nonexistent.toml')
    assert config == defaults


